window.doLogin=async function(){
  var e=$('le').value.trim(),p=$('lp').value;
  if(!e||!p){am('أدخل البريد وكلمة المرور.','er');return}
  try{var c=await signInWithEmailAndPassword(auth,e,p);
    if(!c.user.emailVerified){am('يرجى تفعيل بريدك الإلكتروني أولًا.','in');$('resend').style.display='block'}
  }catch(x){var M={'auth/invalid-credential':'البريد أو كلمة المرور غير صحيحة.','auth/user-not-found':'البريد غير مسجل.','auth/wrong-password':'كلمة المرور غير صحيحة.','auth/too-many-requests':'محاولات كثيرة، حاول لاحقًا.'};am(M[x.code]||x.message,'er')}
};
window.doRegister=async function(){
  var n=$('rn').value.trim(),u=$('ru').value.trim(),e=$('re').value.trim(),ph=$('rph').value.trim(),p=$('rp').value,p2=$('rp2').value,d=picked($('dgrid'));
  if(!n||!u||!e||!ph){am('أكمل كل الحقول.','er');return}
  if(p.length<8){am('كلمة المرور 8 أحرف على الأقل.','er');return}
  if(p!==p2){am('كلمتا المرور غير متطابقتين.','er');return}
  if(!d.length){am('اختر مجالًا واحدًا على الأقل.','er');return}
  try{var c=await createUserWithEmailAndPassword(auth,e,p);
    try{await sendEmailVerification(c.user)}catch(x){console.error(x)}
    try{await saveUser(c.user,{name:n,username:u,phone:ph,domains:d})}catch(x){console.error(x)}
    switchTab('login');am('تم إنشاء الحساب. افتح رابط التفعيل المرسل إلى بريدك (تفقد Spam) ثم سجّل الدخول.','ok');$('resend').style.display='block';
  }catch(x){var M={'auth/email-already-in-use':'هذا البريد مسجل مسبقًا.','auth/invalid-email':'البريد غير صالح.','auth/weak-password':'كلمة المرور ضعيفة.'};am(M[x.code]||x.message,'er')}
};
