async function loadFile(id,cb){
  var m=await retry(function(){return getDoc(doc(db,'khfiles',id))});if(!m.exists())throw new Error('الملف غير موجود');
  var md=m.data(),n=md.n,parts=new Array(n),done=0,i=0;
  async function w(){while(i<n){var k=i++;var s=await retry(function(){return getDoc(doc(db,'khfiles',id,'p',String(k)))});if(!s.exists())throw new Error('جزء مفقود');parts[k]=s.data().d;done++;if(cb)cb(done/n)}}
  await Promise.all([w(),w(),w(),w()]);
  var bytes=parts.map(function(p){var bin=atob(p),u=new Uint8Array(bin.length);for(var j=0;j<bin.length;j++)u[j]=bin.charCodeAt(j);return u});
  return new Blob(bytes,{type:md.kind==='pdf'?'application/pdf':'video/mp4'});
}
