async function relLatest(repo){
  var r=await fetch('https://api.github.com/repos/'+repo+'/releases?per_page=8');
  if(!r.ok)throw new Error(r.status===404?'المستودع غير عام أو غير موجود':'تعذر الاتصال بـ GitHub ('+r.status+')');
  var l=await r.json();l=l.filter(function(x){return !x.draft&&(x.assets||[]).some(function(a){return /\.apk$/i.test(a.name)})});
  if(!l.length)throw new Error('لا توجد إصدارات تحتوي على ملف APK');
  var x=l[0],a=x.assets.filter(function(a){return /\.apk$/i.test(a.name)})[0];
  return {n:parseInt(String(x.tag_name||'').replace(/\D/g,''),10),tag:x.tag_name,url:a.browser_download_url,size:a.size};
}
